53|  const routeParams = useParams();
54|  const param = routeParams?.sceneId;
55|  const routeSceneId = typeof param === "string" ? param : null;
56|  const [manifest, setManifest] = useState<MusicManifest | null>(null);
57|  const [selection, setSelection] = useState<MusicSelection | null>(null);
58|  const [musicFailed, setMusicFailed] = useState(false);
59|  const [currentId, setCurrentId] = useState<string | null>(null);
60|  const [replayNonce, setReplayNonce] = useState(0);
61|  const [fadeSec, setFadeSec] = useState(0);
62|  const [playlistOn, setPlaylistOn] = useState(false);
63|  // Volume and mute persist next to the style in one prefs object; the
64|  // player stays a controlled view over them.
65|  const [volume, setVolume] = useState(() => loadMusicPrefs()?.volume ?? DEFAULT_VOLUME);
66|  const [muted, setMuted] = useState(() => loadMusicPrefs()?.muted ?? false);
67|  // Ref mirrors so persist handlers always save fresh sound values.
68|  const volumeRef = useRef(volume);
69|  volumeRef.current = volume;
70|  const mutedRef = useRef(muted);
71|  mutedRef.current = muted;
72|  const byId = useMemo(() => new Map(scenes.map((s) => [s.id, s.emotion])), [scenes]);
73|  const schedRef = useRef<SchedulerState>(initScheduler());
74|  const historyRef = useRef<string[]>([]);
75|  const observedRef = useRef<string | null>(null);
76|  const liveRef = useRef({ routeSceneId, manifest, selection, currentId, byId, playlistOn });
77|  liveRef.current = { routeSceneId, manifest, selection, currentId, byId, playlistOn };
78|
79|  const nowSec = () => Date.now() / 1000;
80|
81|  const applyDecision = useCallback(
82|    (
83|      decision: {
84|        state: SchedulerState;
85|        switchToId: string | null;
86|        crossfadeSec: number;
87|      },
88|      opts?: { push?: boolean },
89|    ) => {
90|      // A same-id switch (one-track playlist wrap) bails out of setCurrentId,
91|      // so bump a replay nonce the player effect listens to instead.
92|      const prevId = schedRef.current.currentId;
93|      schedRef.current = decision.state;
94|      if (decision.switchToId !== null) {
95|        setFadeSec(decision.crossfadeSec);
96|        if (decision.switchToId === prevId) {
97|          setReplayNonce((n) => n + 1);
98|        } else {
99|          // Every automatic switch banks the outgoing id for Previous.
100|          // The Previous handler passes push false so it never re-banks.
101|          if (opts?.push !== false && prevId !== null) {
102|            historyRef.current = pushHistory(historyRef.current, prevId);
103|          }
104|          setCurrentId(decision.switchToId);
105|        }
106|      }
107|    },
108|    [],
109|  );
110|
111|  const persist = useCallback(
112|    (next: MusicSelection, sound?: { volume: number; muted: boolean }) => {
113|      setSelection(next);
114|      saveMusicPrefs({
115|        style: next.style,
116|        volume: sound?.volume ?? volumeRef.current,
117|        muted: sound?.muted ?? mutedRef.current,
118|      });
119|    },
120|    [],
121|  );
122|
123|  const observe = useCallback(
124|    (sceneId: string) => {
125|      const st = liveRef.current;
126|      if (!st.manifest || !st.selection) return;
127|      const signal = st.byId.get(sceneId) ?? null;
128|      applyDecision(
129|        observeScene(schedRef.current, sceneId, signal, st.manifest, nowSec(), {
130|          selection: st.selection,
131|          rng: Math.random,
132|        }, entryDwell()),
133|      );
134|    },
135|    [applyDecision],
136|  );
137|
138|  useEffect(() => {
139|    let cancelled = false;
140|    fetch("/music/manifest.json")
141|      .then((res) => {
142|        if (!res.ok) throw new Error(`manifest ${res.status}`);
143|        return res.json();
144|      })
145|      .then((json: unknown) => {
146|        if (cancelled) return;
147|        const parsed = parseManifest(json);
148|        setManifest(parsed);
149|        setSelection(resolveInitialSelection(parsed, loadMusicPrefs()));
150|      })
151|      .catch(() => {
152|        if (!cancelled) setMusicFailed(true);
153|      });
154|    return () => {
155|      cancelled = true;
156|    };
157|  }, []);
158|
159|  // Scene entry: exactly one observe call per scene id, once the manifest
160|  // lands. The first scene cues at once, so it plays on the first press.
161|  useEffect(() => {
162|    const gate = nextSceneEntry({
163|      observedId: observedRef.current,
164|      routeId: routeSceneId,
165|      manifestReady: manifest !== null,
166|    });
167|    observedRef.current = gate.nextObservedId;
168|    if (gate.shouldObserve && routeSceneId) observe(routeSceneId);
169|  }, [routeSceneId, manifest, observe]);
170|
171|  useEffect(() => {
172|    // Settle an expired entry dwell, or re-check the scene after a hold.
173|    const timer = window.setInterval(() => {
174|      const st = liveRef.current;
175|      if (!st.manifest || !st.selection || !st.routeSceneId) return;
176|      const sceneId = schedRef.current.pendingSceneId ?? st.routeSceneId;
177|      const signal = st.byId.get(sceneId) ?? null;
178|      applyDecision(
179|        tickScheduler(schedRef.current, signal, st.manifest, nowSec(), {
180|          selection: st.selection,
181|          rng: Math.random,
182|        }, entryDwell()),
183|      );
184|    }, 1000);
185|    return () => window.clearInterval(timer);
186|  }, [applyDecision]);
187|
188|  function skip() {
189|    const st = liveRef.current;
190|    if (!st.manifest || !st.selection || !st.routeSceneId) return;
191|    const signal = st.byId.get(st.routeSceneId) ?? null;
192|    applyDecision(
193|      requestNext(schedRef.current, signal, st.manifest, nowSec(), {
194|        selection: st.selection,
195|        rng: Math.random,
196|      }),
197|    );
198|  }
199|
200|  // Previous: back to the last played track, held like a Next. With no
201|  // history the current track restarts from zero through the replay path,
202|  // including in playlist mode.
203|  function goPrev() {
204|    const st = liveRef.current;
205|    if (!st.manifest || !st.selection) return;
206|    if (st.playlistOn) {
207|      setReplayNonce((n) => n + 1);
208|      return;
209|    }
210|    const popped = popHistory(historyRef.current);
211|    if (!popped) {
212|      setReplayNonce((n) => n + 1);
213|      return;
214|    }
215|    historyRef.current = popped.hist;
216|    applyDecision(
217|      requestManualTrack(schedRef.current, st.manifest, popped.id, nowSec()),
218|      { push: false },
219|    );
220|  }
221|
222|  function togglePlaylist() {
223|    const st = liveRef.current;
224|    if (!st.manifest || !st.selection) return;
225|    const playlist = findChopinPlaylist(st.manifest);
226|    if (!playlist) return;
227|    if (st.playlistOn) {
228|      const signal = (st.routeSceneId && st.byId.get(st.routeSceneId)) || null;
229|      applyDecision(
230|        exitPlaylist(schedRef.current, signal ?? null, st.manifest, nowSec(), {
231|          selection: st.selection,
232|          rng: Math.random,
233|        }),
234|      );
235|      setPlaylistOn(false);
236|      return;
237|    }
238|    applyDecision(enterPlaylist(schedRef.current, st.manifest, playlist.id, nowSec()));
239|    setPlaylistOn(true);
240|  }
241|
242|  function changeVolume(next: number) {
243|    setVolume(next);
244|    volumeRef.current = next;
245|    saveMusicPrefs({
246|      style: liveRef.current.selection?.style ?? null,
247|      volume: next,
248|      muted: mutedRef.current,
249|    });
250|  }
251|
252|  function changeMuted(next: boolean) {
253|    setMuted(next);
254|    mutedRef.current = next;
255|    saveMusicPrefs({
256|      style: liveRef.current.selection?.style ?? null,
257|      volume: volumeRef.current,
258|      muted: next,
259|    });
260|  }
261|
262|  function changeStyle(style: string) {
263|    const st = liveRef.current;
264|    if (!st.manifest || !st.selection || !st.routeSceneId || st.playlistOn) return;
265|    if (style === st.selection.style) return;
266|    const signal = st.byId.get(st.routeSceneId) ?? null;
267|    const decision = switchStyle(schedRef.current, signal, st.manifest, nowSec(), style);
268|    if (decision.switchToId === null) return;
269|    applyDecision(decision);
270|    persist({ style });
271|  }
272|
273|  function ended(trackId: string) {
274|    const st = liveRef.current;
275|    if (!st.manifest || !st.selection || !st.routeSceneId) return;
276|    const signal = st.byId.get(st.routeSceneId) ?? null;
277|    applyDecision(
278|      noteTrackEnded(schedRef.current, signal, st.manifest, trackId, nowSec(), {
279|        selection: st.selection,
280|        rng: Math.random,
281|      }),
282|    );
283|  }
284|
285|  const track: Track | null = manifest?.tracks.find((t) => t.id === currentId) ?? null;
286|  const empty = manifest !== null && manifest.tracks.length === 0;
287|  const activeSignal = (routeSceneId && byId.get(routeSceneId)) || null;
288|  // Styles with at least one emotion-selectable track; hidden while fewer
289|  // than two qualify.
290|  const stylesWithTracks =
291|    manifest?.styles.filter((s) => styleHasTracks(manifest, s.id)) ?? [];
292|  const activePlaylist = manifest ? findChopinPlaylist(manifest) : null;
293|  const canSkip =
294|    manifest !== null &&
295|    selection !== null &&
296|    (playlistOn
297|      ? (activePlaylist?.trackIds.length ?? 0) > 1
298|      : manifest.tracks.length > 1 &&
299|        nextTrack(activeSignal ?? null, manifest, currentId, undefined, selection) !== null);
300|  // Previous restarts the track with no history (including the current
301|  // playlist piece), so it stays on whenever a track is cued.
302|  const canPrev = currentId !== null;
303|
304|  return (
305|    <>
306|      <header className="topbar">
307|        <div className="bar-inner">
308|          <span className="wordmark">Lectoria</span>
309|          {musicFailed || empty ? (
310|            <p className="player-note">Music unavailable. The reader works without it.</p>
311|          ) : (
312|            <Player
313|              track={track}
314|              replayNonce={replayNonce}
315|              fadeSec={fadeSec}
316|              canPrev={canPrev}
317|              onPrev={goPrev}
318|              canSkip={canSkip}
319|              onSkip={skip}
320|              volume={volume}
321|              muted={muted}
322|              onVolumeChange={changeVolume}
323|              onMutedChange={changeMuted}
324|              styles={stylesWithTracks}
325|              styleId={selection?.style ?? null}
326|              onStyleChange={changeStyle}
327|              onEnded={ended}
328|              playlistOn={playlistOn}
329|              playlistLabel={activePlaylist?.label ?? null}
330|              onTogglePlaylist={togglePlaylist}
331|              controlsDisabled={playlistOn}
332|            />
333|          )}
334|        </div>
335|      </header>
336|      {children}
337|    </>
338|  );
339|}

